action.code:
if (hash < 0.0f || hash > 1.0f) {
    LOG(FATAL) << "Hash value must be in [0, 1] range, got " << hash;
    return nullptr;
}

if (partition_to_bucket.empty()) {
    LOG(WARNING) << "No buckets available in partition map";
    return nullptr;
}

auto it = partition_to_bucket.upper_bound(hash);
if (it == partition_to_bucket.end()) {
    it = partition_to_bucket.begin();
}

return it->second;

